import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.C0KMm31j.js";const o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_15_ppo_overview.png",l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_15_probability_ratio.png",h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_15_clip_objective.png",n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_15_training_cycle.png",p="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_15_driving_boundary.png",m=JSON.parse('{"title":"同一批数据多学几轮，策略为什么会崩？PPO 的裁剪目标讲透了","description":"策略梯度依赖当前策略采样的数据。若每批轨迹只更新一次，交互成本很高；若在同一批数据上反复更新，新策略又会逐渐远离产生数据的旧策略，优势估计和状态动作分布不再匹配，策略性能可能突然崩塌。Proximal Policy Optimization（近端策略优化，PPO）试图在两者之间取得平衡：允许对一批 ","frontmatter":{"title":"同一批数据多学几轮，策略为什么会崩？PPO 的裁剪目标讲透了","description":"策略梯度依赖当前策略采样的数据。若每批轨迹只更新一次，交互成本很高；若在同一批数据上反复更新，新策略又会逐渐远离产生数据的旧策略，优势估计和状态动作分布不再匹配，策略性能可能突然崩塌。Proximal Policy Optimization（近端策略优化，PPO）试图在两者之间取得平衡：允许对一批 ","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":15,"source":"2026-08-13/rl_series_15_ppo.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_15_ppo_overview.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-15-ppo"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"同一批数据多学几轮，策略为什么会崩？PPO 的裁剪目标讲透了"}],["meta",{"property":"og:description","content":"策略梯度依赖当前策略采样的数据。若每批轨迹只更新一次，交互成本很高；若在同一批数据上反复更新，新策略又会逐渐远离产生数据的旧策略，优势估计和状态动作分布不再匹配，策略性能可能突然崩塌。Proximal Policy Optimization（近端策略优化，PPO）试图在两者之间取得平衡：允许对一批 "}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-15-ppo"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_15_ppo_overview.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"同一批数据多学几轮，策略为什么会崩？PPO 的裁剪目标讲透了"}],["meta",{"name":"twitter:description","content":"策略梯度依赖当前策略采样的数据。若每批轨迹只更新一次，交互成本很高；若在同一批数据上反复更新，新策略又会逐渐远离产生数据的旧策略，优势估计和状态动作分布不再匹配，策略性能可能突然崩塌。Proximal Policy Optimization（近端策略优化，PPO）试图在两者之间取得平衡：允许对一批 "}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_15_ppo_overview.png"}]],"prev":{"text":"演员负责行动，评论家负责打分：Actor-Critic 为什么能边走边学","link":"/rl/rl-series-14-actor-critic"},"next":{"text":"连续动作不再靠枚举：DDPG 怎样让演员沿着评论家的梯度前进","link":"/rl/rl-series-16-ddpg"}},"headers":[],"relativePath":"rl/rl-series-15-ppo.md","filePath":"rl/rl-series-15-ppo.md","lastUpdated":null}'),s={name:"rl/rl-series-15-ppo.md"};function d(c,a,_,u,b,P){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="同一批数据多学几轮-策略为什么会崩-ppo-的裁剪目标讲透了" tabindex="-1">同一批数据多学几轮，策略为什么会崩？PPO 的裁剪目标讲透了 <a class="header-anchor" href="#同一批数据多学几轮-策略为什么会崩-ppo-的裁剪目标讲透了" aria-label="Permalink to &quot;同一批数据多学几轮，策略为什么会崩？PPO 的裁剪目标讲透了&quot;">​</a></h1><p>策略梯度依赖当前策略采样的数据。若每批轨迹只更新一次，交互成本很高；若在同一批数据上反复更新，新策略又会逐渐远离产生数据的旧策略，优势估计和状态动作分布不再匹配，策略性能可能突然崩塌。Proximal Policy Optimization（近端策略优化，PPO）试图在两者之间取得平衡：允许对一批 On-Policy（同策略）数据进行多轮小批量优化，同时削弱把新旧策略推得过远的更新激励。</p><p>最常用的 PPO-Clip（裁剪式近端策略优化）并没有把策略变化硬性限制在 (1\\pm\\epsilon) 内。它构造新旧动作概率比率，并对替代目标取裁剪后的保守下界。当更新已越过有利区间，目标不再继续奖励这种方向，但优化器仍可能因其他样本、共享参数或过多训练轮次把策略推得更远。因此，裁剪、KL Divergence（KL 散度）监控、优势估计、价值训练与停止条件必须作为一个系统理解。</p><h2 id="一、先给出整篇文章的结论" tabindex="-1">一、先给出整篇文章的结论 <a class="header-anchor" href="#一、先给出整篇文章的结论" aria-label="Permalink to &quot;一、先给出整篇文章的结论&quot;">​</a></h2><h3 id="_1-1-ppo-仍然属于同策略算法" tabindex="-1">1.1 PPO 仍然属于同策略算法 <a class="header-anchor" href="#_1-1-ppo-仍然属于同策略算法" aria-label="Permalink to &quot;1.1 PPO 仍然属于同策略算法&quot;">​</a></h3><p>它可以在当前批次上多轮更新，但数据仍由冻结的旧策略采集。策略更新阶段结束后，需要用新策略重新采样，不能无限复用历史回放池。</p><h3 id="_1-2-概率比率衡量动作行为变化" tabindex="-1">1.2 概率比率衡量动作行为变化 <a class="header-anchor" href="#_1-2-概率比率衡量动作行为变化" aria-label="Permalink to &quot;1.2 概率比率衡量动作行为变化&quot;">​</a></h3><p>$$ r_t(\\theta)=\\frac{\\pi_\\theta(A_t|S_t)}{\\pi_{\\theta_{old}}(A_t|S_t)} $$</p><p>比率大于一表示新策略更偏好已采样动作，小于一表示更不偏好。</p><h3 id="_1-3-裁剪限制的是目标激励-不是参数硬边界" tabindex="-1">1.3 裁剪限制的是目标激励，不是参数硬边界 <a class="header-anchor" href="#_1-3-裁剪限制的是目标激励-不是参数硬边界" aria-label="Permalink to &quot;1.3 裁剪限制的是目标激励，不是参数硬边界&quot;">​</a></h3><p>PPO-Clip 在优势为正或负时分别截断过度有利的概率变化，使继续远离旧策略不再改善该样本目标，但不能保证最终比率和 KL 散度绝不超限。</p><h3 id="_1-4-ppo-的稳定性来自整套实现细节" tabindex="-1">1.4 PPO 的稳定性来自整套实现细节 <a class="header-anchor" href="#_1-4-ppo-的稳定性来自整套实现细节" aria-label="Permalink to &quot;1.4 PPO 的稳定性来自整套实现细节&quot;">​</a></h3><p>GAE（广义优势估计）、优势标准化、价值函数训练、熵奖励、梯度裁剪、KL 提前停止、批次打乱和终止语义都会显著影响结果。</p><p><img src="'+o+'" alt="PPO 在采样旧策略与多轮受限更新之间循环"></p><h2 id="二、为什么普通策略梯度不能随意复用数据" tabindex="-1">二、为什么普通策略梯度不能随意复用数据 <a class="header-anchor" href="#二、为什么普通策略梯度不能随意复用数据" aria-label="Permalink to &quot;二、为什么普通策略梯度不能随意复用数据&quot;">​</a></h2><h3 id="_2-1-轨迹来自旧策略分布" tabindex="-1">2.1 轨迹来自旧策略分布 <a class="header-anchor" href="#_2-1-轨迹来自旧策略分布" aria-label="Permalink to &quot;2.1 轨迹来自旧策略分布&quot;">​</a></h3><p>采样动作时使用 (\\pi_{\\theta_{old}})。一旦参数更新，新的 (\\pi_\\theta) 对相同状态动作赋予不同概率，旧样本不再是新策略的直接同分布样本。</p><h3 id="_2-2-多轮优化会不断扩大分布差异" tabindex="-1">2.2 多轮优化会不断扩大分布差异 <a class="header-anchor" href="#_2-2-多轮优化会不断扩大分布差异" aria-label="Permalink to &quot;2.2 多轮优化会不断扩大分布差异&quot;">​</a></h3><p>单轮小更新后差异可能很小，连续多个 Epoch（训练轮次）后，新策略可能已经明显远离旧策略，原优势估计不再可靠。</p><h3 id="_2-3-一次过大策略变化会破坏数据覆盖" tabindex="-1">2.3 一次过大策略变化会破坏数据覆盖 <a class="header-anchor" href="#_2-3-一次过大策略变化会破坏数据覆盖" aria-label="Permalink to &quot;2.3 一次过大策略变化会破坏数据覆盖&quot;">​</a></h3><p>新策略可能迅速放弃某些动作或状态区域。下一批采样不再覆盖这些区域，错误更新难以纠正，性能可能突然下降。</p><h2 id="三、重要性比率怎样连接新旧策略" tabindex="-1">三、重要性比率怎样连接新旧策略 <a class="header-anchor" href="#三、重要性比率怎样连接新旧策略" aria-label="Permalink to &quot;三、重要性比率怎样连接新旧策略&quot;">​</a></h2><h3 id="_3-1-用旧策略采样-新策略计算目标" tabindex="-1">3.1 用旧策略采样，新策略计算目标 <a class="header-anchor" href="#_3-1-用旧策略采样-新策略计算目标" aria-label="Permalink to &quot;3.1 用旧策略采样，新策略计算目标&quot;">​</a></h3><p>对旧策略数据，可以用动作概率比率修正新旧策略在动作分布上的差异。实践通常保存采样时的旧对数概率。</p><h3 id="_3-2-对数概率差比直接相除稳定" tabindex="-1">3.2 对数概率差比直接相除稳定 <a class="header-anchor" href="#_3-2-对数概率差比直接相除稳定" aria-label="Permalink to &quot;3.2 对数概率差比直接相除稳定&quot;">​</a></h3><p>实现常计算：</p><p>$$ \\log r_t=\\log\\pi_\\theta(A_t|S_t)-\\log\\pi_{\\theta_{old}}(A_t|S_t) $$</p><p>再取指数得到比率，避免直接处理极小概率的除法。</p><h3 id="_3-3-比率只修正已采样动作" tabindex="-1">3.3 比率只修正已采样动作 <a class="header-anchor" href="#_3-3-比率只修正已采样动作" aria-label="Permalink to &quot;3.3 比率只修正已采样动作&quot;">​</a></h3><p>它不是完整轨迹分布的精确重建，也不解决状态访问分布已经改变的问题。PPO 依赖新旧策略足够接近这一近似。</p><h3 id="_3-4-连续动作要使用联合概率" tabindex="-1">3.4 连续动作要使用联合概率 <a class="header-anchor" href="#_3-4-连续动作要使用联合概率" aria-label="Permalink to &quot;3.4 连续动作要使用联合概率&quot;">​</a></h3><p>多维独立高斯策略需要把各动作维度对数概率求和，再计算整体动作比率。逐维分别裁剪会改变标准 PPO 目标含义。</p><p><img src="'+l+'" alt="新旧策略通过已采样动作的概率比率连接"></p><h2 id="四、未裁剪替代目标表达什么" tabindex="-1">四、未裁剪替代目标表达什么 <a class="header-anchor" href="#四、未裁剪替代目标表达什么" aria-label="Permalink to &quot;四、未裁剪替代目标表达什么&quot;">​</a></h2><h3 id="_4-1-基本目标是比率乘旧优势" tabindex="-1">4.1 基本目标是比率乘旧优势 <a class="header-anchor" href="#_4-1-基本目标是比率乘旧优势" aria-label="Permalink to &quot;4.1 基本目标是比率乘旧优势&quot;">​</a></h3><p>$$ L^{PG}(\\theta)=\\mathbb E_t[r_t(\\theta)\\hat A_t] $$</p><p>优势由旧策略批次估计，并在多轮更新期间固定为训练标签。</p><h3 id="_4-2-正优势希望提高动作概率" tabindex="-1">4.2 正优势希望提高动作概率 <a class="header-anchor" href="#_4-2-正优势希望提高动作概率" aria-label="Permalink to &quot;4.2 正优势希望提高动作概率&quot;">​</a></h3><p>当 (\\hat A_t&gt;0) 时，比率越大目标越高，优化器会让新策略更偏好这个比旧策略平均表现更好的动作。</p><h3 id="_4-3-负优势希望降低动作概率" tabindex="-1">4.3 负优势希望降低动作概率 <a class="header-anchor" href="#_4-3-负优势希望降低动作概率" aria-label="Permalink to &quot;4.3 负优势希望降低动作概率&quot;">​</a></h3><p>当 (\\hat A_t&lt;0) 时，比率越小，乘积越接近零，目标越高，优化器会降低较差动作概率。</p><h3 id="_4-4-无限制目标可能把比率推到极端" tabindex="-1">4.4 无限制目标可能把比率推到极端 <a class="header-anchor" href="#_4-4-无限制目标可能把比率推到极端" aria-label="Permalink to &quot;4.4 无限制目标可能把比率推到极端&quot;">​</a></h3><p>同一批数据训练多轮时，好动作概率可能被推得过高，差动作概率被压得过低，策略熵和覆盖迅速下降。</p><h2 id="五、ppo-clip-的目标怎样写" tabindex="-1">五、PPO-Clip 的目标怎样写 <a class="header-anchor" href="#五、ppo-clip-的目标怎样写" aria-label="Permalink to &quot;五、PPO-Clip 的目标怎样写&quot;">​</a></h2><h3 id="_5-1-构造裁剪比率" tabindex="-1">5.1 构造裁剪比率 <a class="header-anchor" href="#_5-1-构造裁剪比率" aria-label="Permalink to &quot;5.1 构造裁剪比率&quot;">​</a></h3><p>$$ \\operatorname{clip}(r_t,1-\\epsilon,1+\\epsilon) $$</p><p>(\\epsilon) 常称裁剪范围，但它不是最终策略变化的硬约束。</p><h3 id="_5-2-对原目标与裁剪目标取最小值" tabindex="-1">5.2 对原目标与裁剪目标取最小值 <a class="header-anchor" href="#_5-2-对原目标与裁剪目标取最小值" aria-label="Permalink to &quot;5.2 对原目标与裁剪目标取最小值&quot;">​</a></h3><p>$$ L^{CLIP}(\\theta)=\\mathbb E_t\\left[\\min\\left(r_t\\hat A_t,\\operatorname{clip}(r_t,1-\\epsilon,1+\\epsilon)\\hat A_t\\right)\\right] $$</p><p>取最小值形成悲观替代目标，避免越过区间后继续获得额外收益。</p><h3 id="_5-3-正负优势的裁剪方向不同" tabindex="-1">5.3 正负优势的裁剪方向不同 <a class="header-anchor" href="#_5-3-正负优势的裁剪方向不同" aria-label="Permalink to &quot;5.3 正负优势的裁剪方向不同&quot;">​</a></h3><p>优势为正时主要限制比率过大；优势为负时主要限制比率过小。只记住“把比率夹在区间”会漏掉 <code>min</code> 与优势符号共同决定的分段行为。</p><p><img src="'+h+'" alt="PPO 裁剪目标对正负优势形成不同的保守边界"></p><h2 id="六、用数字理解正优势样本" tabindex="-1">六、用数字理解正优势样本 <a class="header-anchor" href="#六、用数字理解正优势样本" aria-label="Permalink to &quot;六、用数字理解正优势样本&quot;">​</a></h2><h3 id="_6-1-假设优势为正" tabindex="-1">6.1 假设优势为正 <a class="header-anchor" href="#_6-1-假设优势为正" aria-label="Permalink to &quot;6.1 假设优势为正&quot;">​</a></h3><p>令 (\\hat A=2)，(\\epsilon=0.2)。当比率从 1 增至 1.1，未裁剪目标从 2 增至 2.2，说明提高该动作概率有收益。</p><h3 id="_6-2-超过上界后收益封顶" tabindex="-1">6.2 超过上界后收益封顶 <a class="header-anchor" href="#_6-2-超过上界后收益封顶" aria-label="Permalink to &quot;6.2 超过上界后收益封顶&quot;">​</a></h3><p>当比率为 1.5，未裁剪项为 3，裁剪项为 (1.2\\times2=2.4)，取最小值后目标仍是 2.4。该样本不再奖励继续增大概率。</p><h3 id="_6-3-向错误方向下降不会被上界保护" tabindex="-1">6.3 向错误方向下降不会被上界保护 <a class="header-anchor" href="#_6-3-向错误方向下降不会被上界保护" aria-label="Permalink to &quot;6.3 向错误方向下降不会被上界保护&quot;">​</a></h3><p>若比率降到 0.6，两个候选项取更小的 1.2。策略降低好动作概率会让目标变差，优化器仍有动力纠正。</p><h2 id="七、用数字理解负优势样本" tabindex="-1">七、用数字理解负优势样本 <a class="header-anchor" href="#七、用数字理解负优势样本" aria-label="Permalink to &quot;七、用数字理解负优势样本&quot;">​</a></h2><h3 id="_7-1-假设优势为负" tabindex="-1">7.1 假设优势为负 <a class="header-anchor" href="#_7-1-假设优势为负" aria-label="Permalink to &quot;7.1 假设优势为负&quot;">​</a></h3><p>令 (\\hat A=-2)，(\\epsilon=0.2)。比率从 1 降到 0.9，目标从 -2 变为 -1.8，提高了目标，意味着降低差动作概率。</p><h3 id="_7-2-低于下界后收益封顶" tabindex="-1">7.2 低于下界后收益封顶 <a class="header-anchor" href="#_7-2-低于下界后收益封顶" aria-label="Permalink to &quot;7.2 低于下界后收益封顶&quot;">​</a></h3><p>比率为 0.5 时，未裁剪项为 -1，裁剪项为 (0.8\\times(-2)=-1.6)，取最小值为 -1.6，不再奖励继续压低概率。</p><h3 id="_7-3-向错误方向上升仍会受罚" tabindex="-1">7.3 向错误方向上升仍会受罚 <a class="header-anchor" href="#_7-3-向错误方向上升仍会受罚" aria-label="Permalink to &quot;7.3 向错误方向上升仍会受罚&quot;">​</a></h3><p>若比率升到 1.4，目标为 -2.8，比原来更差。裁剪不会阻止优化器修正增加坏动作概率的方向。</p><h2 id="八、裁剪为什么不是硬约束" tabindex="-1">八、裁剪为什么不是硬约束 <a class="header-anchor" href="#八、裁剪为什么不是硬约束" aria-label="Permalink to &quot;八、裁剪为什么不是硬约束&quot;">​</a></h2><h3 id="_8-1-一个参数同时影响许多样本" tabindex="-1">8.1 一个参数同时影响许多样本 <a class="header-anchor" href="#_8-1-一个参数同时影响许多样本" aria-label="Permalink to &quot;8.1 一个参数同时影响许多样本&quot;">​</a></h3><p>某样本进入平坦区后，其他样本的梯度仍会更新共享参数，从而继续改变该样本概率。</p><h3 id="_8-2-优化器动量可能越过区间" tabindex="-1">8.2 优化器动量可能越过区间 <a class="header-anchor" href="#_8-2-优化器动量可能越过区间" aria-label="Permalink to &quot;8.2 优化器动量可能越过区间&quot;">​</a></h3><p>Adam（自适应矩估计优化器）的动量、学习率和小批次顺序都会让实际更新超过单样本裁剪边界。</p><h3 id="_8-3-概率比率边界不等于-kl-边界" tabindex="-1">8.3 概率比率边界不等于 KL 边界 <a class="header-anchor" href="#_8-3-概率比率边界不等于-kl-边界" aria-label="Permalink to &quot;8.3 概率比率边界不等于 KL 边界&quot;">​</a></h3><p>裁剪只关注批次中已采样动作的比率，KL 散度衡量给定状态下整个动作分布差异。二者相关但不等价。</p><h3 id="_8-4-仍需监控近似-kl-和裁剪比例" tabindex="-1">8.4 仍需监控近似 KL 和裁剪比例 <a class="header-anchor" href="#_8-4-仍需监控近似-kl-和裁剪比例" aria-label="Permalink to &quot;8.4 仍需监控近似 KL 和裁剪比例&quot;">​</a></h3><p>Approximate KL（近似 KL 散度）过大说明策略变化过快，Clip Fraction（裁剪比例）过高说明大量样本已进入平坦区，继续训练可能收益有限。</p><h2 id="九、kl-提前停止怎样补充裁剪" tabindex="-1">九、KL 提前停止怎样补充裁剪 <a class="header-anchor" href="#九、kl-提前停止怎样补充裁剪" aria-label="Permalink to &quot;九、KL 提前停止怎样补充裁剪&quot;">​</a></h2><h3 id="_9-1-每轮更新后估计策略距离" tabindex="-1">9.1 每轮更新后估计策略距离 <a class="header-anchor" href="#_9-1-每轮更新后估计策略距离" aria-label="Permalink to &quot;9.1 每轮更新后估计策略距离&quot;">​</a></h3><p>常见近似使用旧对数概率减新对数概率的批次均值，具体估计式应与实现一致。</p><h3 id="_9-2-超过目标阈值就停止演员更新" tabindex="-1">9.2 超过目标阈值就停止演员更新 <a class="header-anchor" href="#_9-2-超过目标阈值就停止演员更新" aria-label="Permalink to &quot;9.2 超过目标阈值就停止演员更新&quot;">​</a></h3><p>若近似 KL 超过设定阈值，提前结束当前批次剩余策略轮次，减少过度偏离旧策略的风险。</p><h3 id="_9-3-阈值是监控规则而非安全保证" tabindex="-1">9.3 阈值是监控规则而非安全保证 <a class="header-anchor" href="#_9-3-阈值是监控规则而非安全保证" aria-label="Permalink to &quot;9.3 阈值是监控规则而非安全保证&quot;">​</a></h3><p>有限批次 KL 估计可能漏掉未覆盖状态。提前停止改善训练稳定性，不能证明所有状态上的策略变化受限。</p><h2 id="十、ppo-的数据循环如何组织" tabindex="-1">十、PPO 的数据循环如何组织 <a class="header-anchor" href="#十、ppo-的数据循环如何组织" aria-label="Permalink to &quot;十、PPO 的数据循环如何组织&quot;">​</a></h2><h3 id="_10-1-冻结旧策略采集一批-rollout-展开轨迹" tabindex="-1">10.1 冻结旧策略采集一批 Rollout（展开轨迹） <a class="header-anchor" href="#_10-1-冻结旧策略采集一批-rollout-展开轨迹" aria-label="Permalink to &quot;10.1 冻结旧策略采集一批 Rollout（展开轨迹）&quot;">​</a></h3><p>保存状态、动作、奖励、终止与截断、旧对数概率和旧价值预测。采集阶段参数不应在中途改变。</p><h3 id="_10-2-计算回报与优势" tabindex="-1">10.2 计算回报与优势 <a class="header-anchor" href="#_10-2-计算回报与优势" aria-label="Permalink to &quot;10.2 计算回报与优势&quot;">​</a></h3><p>常用 GAE 计算优势，并构造评论家回报目标。自然终止处停止自举，固定长度批次末端若未终止则保留价值。</p><h3 id="_10-3-打乱为多个小批量" tabindex="-1">10.3 打乱为多个小批量 <a class="header-anchor" href="#_10-3-打乱为多个小批量" aria-label="Permalink to &quot;10.3 打乱为多个小批量&quot;">​</a></h3><p>同一批数据被随机打乱，执行若干 Epoch。每次用当前策略重新计算新对数概率，与保存的旧对数概率形成比率。</p><h3 id="_10-4-更新结束后丢弃或归档批次" tabindex="-1">10.4 更新结束后丢弃或归档批次 <a class="header-anchor" href="#_10-4-更新结束后丢弃或归档批次" aria-label="Permalink to &quot;10.4 更新结束后丢弃或归档批次&quot;">​</a></h3><p>下一轮由更新后的策略重新采样。PPO 没有像 DQN 那样从跨越许多旧策略的巨大回放池持续均匀取样。</p><p><img src="'+n+'" alt="PPO 交替执行冻结采样、优势计算和多轮小批量更新"></p><h2 id="十一、gae-在-ppo-中承担什么角色" tabindex="-1">十一、GAE 在 PPO 中承担什么角色 <a class="header-anchor" href="#十一、gae-在-ppo-中承担什么角色" aria-label="Permalink to &quot;十一、GAE 在 PPO 中承担什么角色&quot;">​</a></h2><h3 id="_11-1-ppo-裁剪不负责估计优势" tabindex="-1">11.1 PPO 裁剪不负责估计优势 <a class="header-anchor" href="#_11-1-ppo-裁剪不负责估计优势" aria-label="Permalink to &quot;11.1 PPO 裁剪不负责估计优势&quot;">​</a></h3><p>裁剪只处理策略更新幅度。动作究竟好多少仍由回报、评论家和优势估计决定。</p><h3 id="_11-2-gae-平衡优势偏差与方差" tabindex="-1">11.2 GAE 平衡优势偏差与方差 <a class="header-anchor" href="#_11-2-gae-平衡优势偏差与方差" aria-label="Permalink to &quot;11.2 GAE 平衡优势偏差与方差&quot;">​</a></h3><p>较小 (\\lambda) 更依赖评论家自举，方差低但偏差可能大；较大 (\\lambda) 纳入更长轨迹，偏差可能小但方差增大。</p><h3 id="_11-3-优势通常在批次内标准化" tabindex="-1">11.3 优势通常在批次内标准化 <a class="header-anchor" href="#_11-3-优势通常在批次内标准化" aria-label="Permalink to &quot;11.3 优势通常在批次内标准化&quot;">​</a></h3><p>中心化和缩放能稳定演员梯度尺度，但批次太小会让统计量噪声很大。标准化方式属于算法配置。</p><h3 id="_11-4-评论家质量决定裁剪目标方向" tabindex="-1">11.4 评论家质量决定裁剪目标方向 <a class="header-anchor" href="#_11-4-评论家质量决定裁剪目标方向" aria-label="Permalink to &quot;11.4 评论家质量决定裁剪目标方向&quot;">​</a></h3><p>若优势符号错误，PPO 会稳定地限制错误更新，却不会把错误方向变正确。必须独立监控价值拟合和回报校准。</p><h2 id="十二、价值函数怎样一起训练" tabindex="-1">十二、价值函数怎样一起训练 <a class="header-anchor" href="#十二、价值函数怎样一起训练" aria-label="Permalink to &quot;十二、价值函数怎样一起训练&quot;">​</a></h2><h3 id="_12-1-评论家回归-gae-对应的回报目标" tabindex="-1">12.1 评论家回归 GAE 对应的回报目标 <a class="header-anchor" href="#_12-1-评论家回归-gae-对应的回报目标" aria-label="Permalink to &quot;12.1 评论家回归 GAE 对应的回报目标&quot;">​</a></h3><p>价值损失通常为预测值与 Bootstrapped Return（自举回报）之间的平方误差，演员和评论家可共享特征也可分离。</p><h3 id="_12-2-价值更新次数可能与演员不同" tabindex="-1">12.2 价值更新次数可能与演员不同 <a class="header-anchor" href="#_12-2-价值更新次数可能与演员不同" aria-label="Permalink to &quot;12.2 价值更新次数可能与演员不同&quot;">​</a></h3><p>评论家需要充分拟合当前批次，但过多更新会过拟合。必须报告价值学习率、轮次、批量大小和损失系数。</p><h3 id="_12-3-价值裁剪是可选实现细节" tabindex="-1">12.3 价值裁剪是可选实现细节 <a class="header-anchor" href="#_12-3-价值裁剪是可选实现细节" aria-label="Permalink to &quot;12.3 价值裁剪是可选实现细节&quot;">​</a></h3><p>有些实现限制新旧价值预测变化，有些不使用价值裁剪。它不是原始 PPO-Clip 策略目标的必备定义，比较时要核对代码。</p><h3 id="_12-4-explained-variance-解释方差-辅助诊断" tabindex="-1">12.4 Explained Variance（解释方差）辅助诊断 <a class="header-anchor" href="#_12-4-explained-variance-解释方差-辅助诊断" aria-label="Permalink to &quot;12.4 Explained Variance（解释方差）辅助诊断&quot;">​</a></h3><p>该指标衡量价值预测解释回报变化的程度。接近一通常更好，接近零说明不比常数强，负值可能表示预测方向很差，但它仍不是策略性能指标。</p><h2 id="十三、熵奖励和动作尺度怎样影响-ppo" tabindex="-1">十三、熵奖励和动作尺度怎样影响 PPO <a class="header-anchor" href="#十三、熵奖励和动作尺度怎样影响-ppo" aria-label="Permalink to &quot;十三、熵奖励和动作尺度怎样影响 PPO&quot;">​</a></h2><h3 id="_13-1-熵奖励延缓策略塌缩" tabindex="-1">13.1 熵奖励延缓策略塌缩 <a class="header-anchor" href="#_13-1-熵奖励延缓策略塌缩" aria-label="Permalink to &quot;13.1 熵奖励延缓策略塌缩&quot;">​</a></h3><p>熵系数鼓励动作分布保持宽度。连续高斯策略中，熵与标准差直接相关，需要监控各动作维度尺度。</p><h3 id="_13-2-动作归一化改善优化条件" tabindex="-1">13.2 动作归一化改善优化条件 <a class="header-anchor" href="#_13-2-动作归一化改善优化条件" aria-label="Permalink to &quot;13.2 动作归一化改善优化条件&quot;">​</a></h3><p>把物理动作映射到相近数值范围，有助于均值和标准差学习。映射、压缩和实际执行动作必须保持一致。</p><h3 id="_13-3-tanh-压缩需要概率校正" tabindex="-1">13.3 Tanh 压缩需要概率校正 <a class="header-anchor" href="#_13-3-tanh-压缩需要概率校正" aria-label="Permalink to &quot;13.3 Tanh 压缩需要概率校正&quot;">​</a></h3><p>先采样高斯变量再经 Tanh 变换时，严格对数概率需包含变量变换的 Jacobian（雅可比行列式）校正。不同 PPO 实现可能选择直接裁剪，必须核对语义。</p><h2 id="十四、哪些超参数最容易互相耦合" tabindex="-1">十四、哪些超参数最容易互相耦合 <a class="header-anchor" href="#十四、哪些超参数最容易互相耦合" aria-label="Permalink to &quot;十四、哪些超参数最容易互相耦合&quot;">​</a></h2><h3 id="_14-1-学习率与更新轮次共同决定步幅" tabindex="-1">14.1 学习率与更新轮次共同决定步幅 <a class="header-anchor" href="#_14-1-学习率与更新轮次共同决定步幅" aria-label="Permalink to &quot;14.1 学习率与更新轮次共同决定步幅&quot;">​</a></h3><p>较小学习率配合很多轮次，最终也可能产生大策略变化；只调裁剪范围而忽略轮次无法控制更新强度。</p><h3 id="_14-2-批次大小影响优势统计与-kl-估计" tabindex="-1">14.2 批次大小影响优势统计与 KL 估计 <a class="header-anchor" href="#_14-2-批次大小影响优势统计与-kl-估计" aria-label="Permalink to &quot;14.2 批次大小影响优势统计与 KL 估计&quot;">​</a></h3><p>采样批次太小会增加优势标准化和 KL 监控噪声，太大则提高等待时间和内存占用。</p><h3 id="_14-3-小批量大小影响梯度噪声" tabindex="-1">14.3 小批量大小影响梯度噪声 <a class="header-anchor" href="#_14-3-小批量大小影响梯度噪声" aria-label="Permalink to &quot;14.3 小批量大小影响梯度噪声&quot;">​</a></h3><p>小批量更小会增加更新随机性，同一批数据被访问次数也变化。需要结合 Epoch 数计算每个样本的复用次数。</p><h3 id="_14-4-裁剪范围不是独立旋钮" tabindex="-1">14.4 裁剪范围不是独立旋钮 <a class="header-anchor" href="#_14-4-裁剪范围不是独立旋钮" aria-label="Permalink to &quot;14.4 裁剪范围不是独立旋钮&quot;">​</a></h3><p>(\\epsilon) 与优势尺度、学习率、网络结构和 KL 停止共同决定实际策略变化。不能跨任务机械复制一个数值。</p><h2 id="十五、训练时应该监控哪些指标" tabindex="-1">十五、训练时应该监控哪些指标 <a class="header-anchor" href="#十五、训练时应该监控哪些指标" aria-label="Permalink to &quot;十五、训练时应该监控哪些指标&quot;">​</a></h2><h3 id="_15-1-策略相关指标" tabindex="-1">15.1 策略相关指标 <a class="header-anchor" href="#_15-1-策略相关指标" aria-label="Permalink to &quot;15.1 策略相关指标&quot;">​</a></h3><p>记录近似 KL、裁剪比例、策略熵、动作标准差、策略损失和演员梯度范数。</p><h3 id="_15-2-价值相关指标" tabindex="-1">15.2 价值相关指标 <a class="header-anchor" href="#_15-2-价值相关指标" aria-label="Permalink to &quot;15.2 价值相关指标&quot;">​</a></h3><p>记录价值损失、解释方差、预测值范围、回报目标范围和评论家梯度范数。</p><h3 id="_15-3-数据与结果指标" tabindex="-1">15.3 数据与结果指标 <a class="header-anchor" href="#_15-3-数据与结果指标" aria-label="Permalink to &quot;15.3 数据与结果指标&quot;">​</a></h3><p>记录环境步数、回合长度、终止原因、训练回报、独立评估回报与安全事件。优化步数不能替代环境交互预算。</p><h3 id="_15-4-多随机种子与失败率" tabindex="-1">15.4 多随机种子与失败率 <a class="header-anchor" href="#_15-4-多随机种子与失败率" aria-label="Permalink to &quot;15.4 多随机种子与失败率&quot;">​</a></h3><p>PPO 相对易用不等于确定稳定。应报告中位数、分散程度、最差种子和达到性能阈值的环境步数。</p><h2 id="十六、自动驾驶中怎样使用-ppo" tabindex="-1">十六、自动驾驶中怎样使用 PPO <a class="header-anchor" href="#十六、自动驾驶中怎样使用-ppo" aria-label="Permalink to &quot;十六、自动驾驶中怎样使用 PPO&quot;">​</a></h2><h3 id="_16-1-连续动作适合仿真策略学习" tabindex="-1">16.1 连续动作适合仿真策略学习 <a class="header-anchor" href="#_16-1-连续动作适合仿真策略学习" aria-label="Permalink to &quot;16.1 连续动作适合仿真策略学习&quot;">​</a></h3><p>PPO 可输出连续曲率、加速度或轨迹参数，也能处理离散高层决策，适合构建统一策略实验基线。</p><h3 id="_16-2-同策略采样成本必须正视" tabindex="-1">16.2 同策略采样成本必须正视 <a class="header-anchor" href="#_16-2-同策略采样成本必须正视" aria-label="Permalink to &quot;16.2 同策略采样成本必须正视&quot;">​</a></h3><p>高保真仿真每步成本高，PPO 又需要不断用新策略采样。并行环境可提高吞吐，但不会减少所需环境步数。</p><h3 id="_16-3-安全约束不能由裁剪替代" tabindex="-1">16.3 安全约束不能由裁剪替代 <a class="header-anchor" href="#_16-3-安全约束不能由裁剪替代" aria-label="Permalink to &quot;16.3 安全约束不能由裁剪替代&quot;">​</a></h3><p>PPO 裁剪限制策略优化激励，不限制车辆状态或动作满足安全集合。仍需独立安全屏蔽、控制屏障函数或约束强化学习方法。</p><h3 id="_16-4-策略更新前后要做场景回归" tabindex="-1">16.4 策略更新前后要做场景回归 <a class="header-anchor" href="#_16-4-策略更新前后要做场景回归" aria-label="Permalink to &quot;16.4 策略更新前后要做场景回归&quot;">​</a></h3><p>每轮候选模型应在固定典型、边界和反事实场景集上评估，观察碰撞、越界、舒适性、规则违例与安全层介入率。</p><p><img src="'+p+'" alt="PPO 策略部署前仍需经过场景回归和独立安全约束"></p><h2 id="十七、一个最小复现实验怎样设计" tabindex="-1">十七、一个最小复现实验怎样设计 <a class="header-anchor" href="#十七、一个最小复现实验怎样设计" aria-label="Permalink to &quot;十七、一个最小复现实验怎样设计&quot;">​</a></h2><h3 id="_17-1-先用同一-actor-critic-基线" tabindex="-1">17.1 先用同一 Actor-Critic 基线 <a class="header-anchor" href="#_17-1-先用同一-actor-critic-基线" aria-label="Permalink to &quot;17.1 先用同一 Actor-Critic 基线&quot;">​</a></h3><p>固定策略与价值网络、GAE、奖励、采样批次和随机种子，只把普通策略目标替换为 PPO-Clip，避免多因素同时变化。</p><h3 id="_17-2-扫描更新强度组合" tabindex="-1">17.2 扫描更新强度组合 <a class="header-anchor" href="#_17-2-扫描更新强度组合" aria-label="Permalink to &quot;17.2 扫描更新强度组合&quot;">​</a></h3><p>组合比较学习率、Epoch 数和裁剪范围，记录近似 KL、裁剪比例与回报，寻找策略变化和样本复用之间的合理区域。</p><h3 id="_17-3-增加-kl-提前停止消融" tabindex="-1">17.3 增加 KL 提前停止消融 <a class="header-anchor" href="#_17-3-增加-kl-提前停止消融" aria-label="Permalink to &quot;17.3 增加 KL 提前停止消融&quot;">​</a></h3><p>比较无停止与有停止版本，观察过大 KL、性能崩塌和实际执行轮次，验证停止机制是否真正介入。</p><h3 id="_17-4-保存旧概率一致性测试" tabindex="-1">17.4 保存旧概率一致性测试 <a class="header-anchor" href="#_17-4-保存旧概率一致性测试" aria-label="Permalink to &quot;17.4 保存旧概率一致性测试&quot;">​</a></h3><p>在任何参数更新前，新旧策略相同，所有样本比率应接近一。若不成立，说明动作预处理、对数概率维度或旧策略保存存在错误。</p><h2 id="十八、最常见的实现错误" tabindex="-1">十八、最常见的实现错误 <a class="header-anchor" href="#十八、最常见的实现错误" aria-label="Permalink to &quot;十八、最常见的实现错误&quot;">​</a></h2><h3 id="_18-1-每轮都覆盖旧对数概率" tabindex="-1">18.1 每轮都覆盖旧对数概率 <a class="header-anchor" href="#_18-1-每轮都覆盖旧对数概率" aria-label="Permalink to &quot;18.1 每轮都覆盖旧对数概率&quot;">​</a></h3><p>旧概率必须固定为采样策略的概率。若每个 Epoch 都更新 <code>old_log_prob</code>，比率会反复回到一，裁剪失去意义。</p><h3 id="_18-2-只裁剪比率后直接乘优势" tabindex="-1">18.2 只裁剪比率后直接乘优势 <a class="header-anchor" href="#_18-2-只裁剪比率后直接乘优势" aria-label="Permalink to &quot;18.2 只裁剪比率后直接乘优势&quot;">​</a></h3><p>标准目标需要对未裁剪项与裁剪项取最小值。只使用裁剪比率会在不应裁剪的错误方向也截断纠正梯度。</p><h3 id="_18-3-优势在每个小批量单独重算" tabindex="-1">18.3 优势在每个小批量单独重算 <a class="header-anchor" href="#_18-3-优势在每个小批量单独重算" aria-label="Permalink to &quot;18.3 优势在每个小批量单独重算&quot;">​</a></h3><p>若优势标准化统计随小批量变化，同一样本权重取决于分批顺序。常见做法是在完整采样批次上先计算并固定优势。</p><h3 id="_18-4-自然终止与采样段结束混为一谈" tabindex="-1">18.4 自然终止与采样段结束混为一谈 <a class="header-anchor" href="#_18-4-自然终止与采样段结束混为一谈" aria-label="Permalink to &quot;18.4 自然终止与采样段结束混为一谈&quot;">​</a></h3><p>固定长度 Rollout 的最后状态不一定终止，需要评论家自举。否则每段末尾价值都会被系统性低估。</p><h3 id="_18-5-训练和评估动作模式混用" tabindex="-1">18.5 训练和评估动作模式混用 <a class="header-anchor" href="#_18-5-训练和评估动作模式混用" aria-label="Permalink to &quot;18.5 训练和评估动作模式混用&quot;">​</a></h3><p>训练按策略采样，评估常取均值或众数。若评估仍随机，方差中混入探索；若训练取均值，保存的随机策略概率与行为不一致。</p><h2 id="十九、学到什么程度才算真正掌握" tabindex="-1">十九、学到什么程度才算真正掌握 <a class="header-anchor" href="#十九、学到什么程度才算真正掌握" aria-label="Permalink to &quot;十九、学到什么程度才算真正掌握&quot;">​</a></h2><h3 id="_19-1-能按优势符号解释裁剪分段" tabindex="-1">19.1 能按优势符号解释裁剪分段 <a class="header-anchor" href="#_19-1-能按优势符号解释裁剪分段" aria-label="Permalink to &quot;19.1 能按优势符号解释裁剪分段&quot;">​</a></h3><p>应能手算正优势和负优势样本在比率区间内外的目标，理解为什么上界和下界分别限制不同方向。</p><h3 id="_19-2-能解释-ppo-为何仍是同策略" tabindex="-1">19.2 能解释 PPO 为何仍是同策略 <a class="header-anchor" href="#_19-2-能解释-ppo-为何仍是同策略" aria-label="Permalink to &quot;19.2 能解释 PPO 为何仍是同策略&quot;">​</a></h3><p>同一采样批次可复用若干轮，不代表可以无限使用跨越许多旧策略的数据。每轮更新后仍需重新采样。</p><h3 id="_19-3-能区分裁剪、kl-与安全约束" tabindex="-1">19.3 能区分裁剪、KL 与安全约束 <a class="header-anchor" href="#_19-3-能区分裁剪、kl-与安全约束" aria-label="Permalink to &quot;19.3 能区分裁剪、KL 与安全约束&quot;">​</a></h3><p>裁剪限制替代目标激励，KL 衡量策略行为距离，车辆安全约束限制物理状态与动作，三者不能互相替代。</p><h3 id="_19-4-能建立完整诊断闭环" tabindex="-1">19.4 能建立完整诊断闭环 <a class="header-anchor" href="#_19-4-能建立完整诊断闭环" aria-label="Permalink to &quot;19.4 能建立完整诊断闭环&quot;">​</a></h3><p>看到回报下降时，应联合检查 KL、裁剪比例、熵、动作尺度、优势、价值解释方差、终止统计和多种子表现，而不是只调裁剪范围。</p><h3 id="_19-5-能看见后续路线" tabindex="-1">19.5 能看见后续路线 <a class="header-anchor" href="#_19-5-能看见后续路线" aria-label="Permalink to &quot;19.5 能看见后续路线&quot;">​</a></h3><p>PPO 解决的是同策略更新稳定与有限数据复用。后续可以继续学习 DDPG（深度确定性策略梯度）、TD3（双延迟深度确定性策略梯度）和 SAC（软演员—评论家），理解连续控制中的异策略回放与熵正则。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p><a href="https://github.com/datawhalechina/easy-rl/blob/master/docs/chapter5/chapter5.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第五章 PPO 算法</a></p><p><a href="https://arxiv.org/abs/1707.06347" target="_blank" rel="noreferrer">Schulman 等《Proximal Policy Optimization Algorithms》</a></p><p><a href="https://spinningup.openai.com/en/latest/algorithms/ppo.html" target="_blank" rel="noreferrer">OpenAI Spinning Up PPO 文档</a></p><p><a href="https://arxiv.org/abs/1502.05477" target="_blank" rel="noreferrer">Schulman 等《Trust Region Policy Optimization》</a></p><p><a href="https://arxiv.org/abs/1506.02438" target="_blank" rel="noreferrer">Schulman 等《High-Dimensional Continuous Control Using Generalized Advantage Estimation》</a></p>',183)])])}const f=e(s,[["render",d]]);export{m as __pageData,f as default};
